INSERT INTO "hexagrams" VALUES(1,'乾为天','111111','上上卦','上上卦','乾','乾','{"text":"乾：元，亨，利，贞。","vernacular":"《乾卦》象征天：元始，亨通，和谐，贞正。","image":"天行健，君子以自强不息。","imageVernacular":"《象辞》说：天道运行周而复始，永无止息，谁也不能阻挡，君子应效法天道，自立自强，不停地奋斗下去。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":583,"endChar":1459,"startLine":74,"endLine":117},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E4%B9%BE&oldid=2404991&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(2,'坤为地','000000','上上卦','上上卦','坤','坤','{"text":"坤：元，亨，利牝马之贞。君子有攸往，先迷，后得主，利。西南得朋，东北丧朋。安贞吉。","vernacular":"《坤卦》象征地：元始，亨通，如果像雌马那样柔顺，则是吉利的。君子从事某项事业，虽然开始时不知所从，但结果会是有利的。如往西南方，则会得到朋友的帮助。如往东北方，则会失去朋友的帮助。如果保持现状，也是吉利的。","image":"地势坤，君子以厚德载物。","imageVernacular":"《象辞》说：坤象征大地，君子应效法大地，胸怀宽广，包容万物。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":1459,"endChar":2508,"startLine":118,"endLine":161},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%9D%A4&oldid=2404999&variant=zh-hans","patchIds":["edit-0003"]}');
INSERT INTO "hexagrams" VALUES(3,'水雷屯','100010','下下卦','下下卦','坎','震','{"text":"屯：元，亨，利，贞；勿用有攸往，利建侯。","vernacular":"《屯卦》象征初生：元始，亨通，和谐，贞正。不要急于发展，首先要立君建国。","image":"云雷屯，君子以经纶。","imageVernacular":"《象辞》说：《屯卦》的卦象是震（雷）下坎（水）上，为雷上有水之表象，水在上表示雨尚未落，故释为云。云雷大作，是即将下雨的征兆，故《屯卦》象征初生。这里表示天地初创，国家始建，正人君子应以全部才智投入到创建国家的事业中去。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":2508,"endChar":3492,"startLine":162,"endLine":199},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%B1%AF&oldid=10643482&variant=zh-hans","patchIds":["edit-0004","edit-0005","edit-0006","edit-0007"]}');
INSERT INTO "hexagrams" VALUES(4,'山水蒙','010001','中下卦','中下卦','艮','坎','{"text":"蒙：亨。匪我求童蒙，童蒙求我；初筮告，再三渎，渎则不告。利贞。","vernacular":"《蒙卦》象征启蒙：亨通。不是我有求于幼童，而是幼童有求于我，第一次向我请教，我有问必答，如果一而再、再而三地没有礼貌地乱问，则不予回答。利于守正道。","image":"山下出泉，蒙；君子以果行育德。","imageVernacular":"《象辞》说：“《蒙卦》的卦象是坎（水）下艮（山）上，为山下有泉水之表象，但要想发现甘泉，必须设法准确地找出泉水的位置，即意味着先必须进行启蒙教育。君子必须行动果断，才能培养出良好的品德。”"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":3492,"endChar":4641,"startLine":200,"endLine":238},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%92%99&oldid=10645379&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(5,'水天需','111010','中上卦','中上卦','坎','乾','{"text":"需：有孚，光亨，贞吉，利涉大川。","vernacular":"《需卦》象征等待：具有诚实守信的品德，光明正大，做事才会亨通顺利，占问的结果是吉祥的，出外远行，渡过宽阔的河流会很顺利。","image":"云上于天，需；君子以饮食宴乐。","imageVernacular":"《象辞》说：《需卦》的卦象是乾（天）下坎（水）上，为水在天上之表象。水汽聚集天上成为云层，密云满天，但还没有下雨，需要等待；君子在这个时候需要吃喝，饮酒作乐，即在等待的时候积蓄力量。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":4641,"endChar":5668,"startLine":239,"endLine":277},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E9%9C%80&oldid=10643261&variant=zh-hans","patchIds":["edit-0008"]}');
INSERT INTO "hexagrams" VALUES(6,'天水讼','010111','中下卦','中下卦','乾','坎','{"text":"讼：有孚窒惕，中吉；终凶，利见大人，不利涉大川。","vernacular":"《讼卦》象征打官司：这是因为诚实守信的德行被阻塞，心中畏惧有所戒备引起，坚守正道居中不偏会有吉祥；坚持把官司打到底则有凶险，如有德高望重的大人物出现则会有利，但出外远行、要渡过宽阔的大河则不会顺利。","image":"天与水违行，讼；君子以作事谋始。","imageVernacular":"《象辞》说《讼卦》的卦象是坎（水）下乾（天）上，为天在水上之表象。天从东向西转动，江河百川之水从西向东流，天与水是逆向相背而行的，象征着人们由于意见不合而打官司。所以君子在做事前要深谋远虑，从开始就要消除可能引起争端的因素。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":5668,"endChar":6840,"startLine":278,"endLine":316},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%A8%9F&oldid=10645409&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(7,'地水师','010000','中上卦','中上卦','坤','坎','{"text":"师：贞，丈人吉，无咎。","vernacular":"《师卦》象征兵众（师指军队）：坚守正道，德高望重富有经验的长者统帅军队可以得到吉祥，不会有什么灾祸。","image":"地中有水，师；君子以容民畜众。","imageVernacular":"《象辞》说：《师卦》的卦象是坎（水）下坤（地）上，是地中有水之表象。地中蕴藏聚集了大量的水，取之不尽，用之不竭，象征兵源充足；君子要像地中藏水一样容纳天下百姓，养育众人，这样就会有众多的士兵可用。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":6840,"endChar":7997,"startLine":317,"endLine":355},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%B8%AB&oldid=2405011&variant=zh-hans","patchIds":["edit-0009"]}');
INSERT INTO "hexagrams" VALUES(8,'水地比','000010','上上卦','上上卦','坎','坤','{"text":"比：吉。原筮，元永贞，无咎。不宁方来，后夫凶。","vernacular":"《比卦》象征亲密无间，团结互助：吉祥。探本求原，再一次卜筮占问，知道要辅佐有德行的长者，长久不变地坚守正道，不会有祸害。连不安分的诸侯现在也来朝贺，还有少数来得迟的诸侯将有凶险。","image":"地上有水，比；先王以建万国，亲诸侯。","imageVernacular":"《象辞》说：《比卦》的卦象为坤（地）下坎（水）上，象征地上有水。大地上百川争流，流水又浸润着大地，表明地与水亲密无间，互相依存；以前的历代君主明白这个道理，所以分封土地，建立万国，安抚亲近各地诸侯。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":7997,"endChar":9131,"startLine":356,"endLine":394},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%AF%94&oldid=10645543&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(9,'风天小畜','111011','下下卦','下下卦','巽','乾','{"text":"小畜：亨；密云不雨，自我西郊。","vernacular":"《小畜卦》象征小有积蓄：亨通顺利；天空布满浓密的积云，但还没有下雨，云气是从城西郊区升起来的。","image":"风行天上，“小畜”；君子以懿文德。","imageVernacular":"《象辞》说：《小畜卦》的卦象是乾（天）下巽（风）上，是风飘行天上的表象。风在天上吹，密云不雨，气候不好不坏，收成一般，所以只能“小有积蓄”；君子面对这种情况，于是修养美好的品德，用心做好文章等待发达的时机。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":9131,"endChar":10166,"startLine":395,"endLine":433},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%B0%8F%E7%95%9C&oldid=10645530&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(10,'天泽履','110111','中上卦','中上卦','乾','兑','{"text":"履：履虎尾，不咥人，亨。","vernacular":"《履卦》象征小心行动：跟在老虎尾巴后面走路，老虎却没有回头咬人，当然亨通顺利。","image":"上天下泽，“履”；君子以辨上下，定民志。","imageVernacular":"《象辞》说：《履卦》的卦象是兑（泽）下乾（天）上，为天下有泽之表象。上有天，下有泽，说明要处处小心行动，如行在沼泽之上，一不注意就会陷下去；君子要深明大义，分清上下尊卑名分，坚定百姓的意志，遵循礼仪而行，必然秩序井然。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":10166,"endChar":11241,"startLine":434,"endLine":472},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%B1%A5&oldid=10647513&variant=zh-hans","patchIds":["edit-0010"]}');
INSERT INTO "hexagrams" VALUES(11,'地天泰','111000','中中卦','中中卦','坤','乾','{"text":"泰：小往大来，吉，亨。","vernacular":"《泰卦》象征通达：这时弱小者离去，强大者到来，吉祥，亨通。","image":"天地交，泰；后以财成天地之道，辅相天地之宜，以左右民。","imageVernacular":"《象辞》说：《泰卦》的卦象为乾（天）下坤（地）上，地气上升，乾气下降，为地气居于乾气之上之表象，陰陽二气一升一降，互相交合，顺畅通达；君主这时要掌握时机，善于裁节调理，以成就天地交合之道，促成天地化生万物之机宜，护佑天下百姓，使他们安居乐业。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":11241,"endChar":12450,"startLine":473,"endLine":511},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%B3%B0&oldid=2106138&variant=zh-hans","patchIds":["edit-0011","edit-0012"]}');
INSERT INTO "hexagrams" VALUES(12,'天地否','000111','中中卦','中中卦','乾','坤','{"text":"否：否之匪人，不利，君子贞；大往小来。","vernacular":"《否卦》象征闭塞：一个卦闭的社会，人们之间的来往是不通畅的，天下没有便利之处，君子必须坚守正道；这时强大者离去，弱小者到来。","image":"天地不交，“否”；君子以俭德辟难，不可荣以禄。","imageVernacular":"《象辞》说：《否卦》的卦象为坤（地）下乾（天）上，为天在地上之表象。天在极高之处，地在极低之处，天地陰陽之间因而不能互相交合，所以时世闭塞不通，这时候君子必须坚持勤俭节约的美德，以避开危险与灾难不能谋取高官及丰厚的俸禄，去追求荣华富贵。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":12450,"endChar":13512,"startLine":512,"endLine":550},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%90%A6&oldid=10645603&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(13,'天火同人','101111','中上卦','中上卦','乾','离','{"text":"同人，同人于野，亨，利涉大川，利君子贞。","vernacular":"《同人卦》象征与人和睦相处：和别人亲密地走在宽广的原野上，亨通，有利于渡过大河急流，有利于君子坚守正道。","image":"天与火，同人；君子以类族辨物。","imageVernacular":"《象辞》说：《同人卦》的卦象是离（火）下乾（天）上，为天下有火之表象。天在高处，火势熊熊而上，天与火亲和相处，君子要明白物以类聚，人以群分的道理，明辨事物，求同存异，团结众人以治理天下。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":13512,"endChar":14551,"startLine":551,"endLine":589},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%90%8C%E4%BA%BA&oldid=10645635&variant=zh-hans","patchIds":["edit-0013"]}');
INSERT INTO "hexagrams" VALUES(14,'火天大有','111101','上上卦','上上卦','离','乾','{"text":"大有：元亨。","vernacular":"《大有卦》象征大有收获：至为亨通。","image":"火在天上，“大有”；君子以遏恶扬善，顺天休命。","imageVernacular":"《象辞》说：《大有卦》的卦象是乾（天）下离（火）上，为火在天上之表象。火焰高悬于天上，象征太陽照耀万物，世界一片光明，农业大丰收，“大有收获”。君子在这个时候要阻止邪恶，颂扬一切善行，顺应天命，替天行道，以保护万物性命。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":14551,"endChar":15583,"startLine":590,"endLine":627},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%A7%E6%9C%89&oldid=10645712&variant=zh-hans","patchIds":["edit-0014","edit-0015","edit-0016","edit-0017"]}');
INSERT INTO "hexagrams" VALUES(15,'地山谦','001000','中中卦','中中卦','坤','艮','{"text":"谦：亨，君子有终。","vernacular":"《谦卦》象征谦虚：谦虚的美德可以使百事顺利，但谦虚并不是人人都能坚持下去的，而只有君子才能坚持到底。","image":"地中有山，谦。君子以裒多益寡，称物平施。","imageVernacular":"《象辞》说：“《谦卦》的卦象是艮（山）下坤（地）上，为高山隐藏于地中之表象，象征高才美德隐藏于心中而不外露，所以称作谦。君子总是损多益少，衡量各种事物，然后取长补短，使其平均。”"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":15583,"endChar":16543,"startLine":628,"endLine":666},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%AC%99&oldid=2106142&variant=zh-hans","patchIds":["edit-0018","edit-0019"]}');
INSERT INTO "hexagrams" VALUES(16,'雷地豫','000100','中中卦','中中卦','震','坤','{"text":"豫：利建侯行师。","vernacular":"《豫卦》象征欢乐愉快：有利于建立诸侯的伟大功业，有利于出师南征北战。","image":"“雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。”","imageVernacular":"《象辞》说：《豫卦》的卦象为坤（地）下震（雷）上，为地上响雷之表象。雷在地上轰鸣，使大地振奋起来，这就是大自然愉快高兴的表现。上古圣明的君主，根据大自然欢乐愉快时雷鸣地震的情景创造了音乐，并用音乐来崇尚推广伟大的功德。他们以盛大隆重的仪礼，把音乐献给天帝，并用它来祭祀自己的祖先。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":16543,"endChar":17722,"startLine":667,"endLine":705},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%B1%AB&oldid=10645735&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(17,'泽雷随','100110','中中卦','中中卦','兑','震','{"text":"随：元，亨，利，贞，无咎。","vernacular":"《随卦》象征随从，随和：如果随从、随和，便能始终亨通，和谐有利。固守正道，没有任何危险。","image":"泽中有雷，随；君子以向晦入宴息。","imageVernacular":"《象辞》说：《随卦》的卦象是震（雷）下兑（泽）上，为泽中有雷之表象。泽中有雷声，泽随从雷声而震动，这便象征随从。君子行事要遵从合适的作息时间。白天出处辛劳工作，夜晚就回家睡觉安息。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":17722,"endChar":18817,"startLine":706,"endLine":744},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E9%9A%A8&oldid=10645020&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(18,'山风蛊','011001','中中卦','中中卦','艮','巽','{"text":"蛊：元亨，利涉大川；先甲三日，后甲三日。","vernacular":"《蛊卦》象征救弊治乱，拨乱反正：从开始就很亨通，有利于涉越大河。不过，在做大事以前，要考察现状、分析事态；在做大事以后，要讲究治理措施，预计到后果。","image":"“山下有风，蛊；君子以振民育德。”","imageVernacular":"《象辞》说：《蛊卦》的卦象是巽（风）下艮（山）上，为山下起大风之表象，象征救弊治乱、拨乱反正。这时候，君子救济人民，培育美德，纠正时弊。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":18817,"endChar":19739,"startLine":745,"endLine":783},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%A0%B1&oldid=2106145&variant=zh-hans","patchIds":["edit-0020"]}');
INSERT INTO "hexagrams" VALUES(19,'地泽临','110000','中上卦','中上卦','坤','兑','{"text":"临：元，亨，利，贞。至于八月有凶。","vernacular":"《临卦》象征督导：能亨通无阻，祥和有益，坚守正道。但是到了八月（陽衰陰盛），会有凶险。","image":"“泽上有地，临；君子以教思无穷，容保民无疆。”","imageVernacular":"《象辞》说：《临卦》的卦象是兑（泽）下坤（地）上，为地在泽上之表象。泽上有地，地居高而临下，象征督导。君子由此受到启发，费尽心思地教导人民，并以其无边无际的盛德保护人民。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":19739,"endChar":20661,"startLine":784,"endLine":822},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%87%A8&oldid=2106146&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(20,'风地观','000011','中上卦','中上卦','巽','坤','{"text":"观：盥而不荐，有孚顒若。","vernacular":"《观卦》象征瞻仰：瞻仰了祭祀开头盛大的倾酒灌地的降神仪式，就可以不去看后面的献饗之礼了，因为这时心中已经充满了诚敬肃穆的情绪。","image":"风行地上，观；先王以省方观民设教。","imageVernacular":"《象辞》说：《观卦》的卦象是坤（地）下巽（风）上，为风吹拂于地上而遍及万物之表象，象征瞻仰。先代君王仿效风吹拂于地而遍及万物的精神，视察四方，留心民风民俗，用教育来感化民众。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":20661,"endChar":21614,"startLine":823,"endLine":861},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%A7%80&oldid=10645159&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(21,'火雷噬嗑','100101','上上卦','上上卦','离','震','{"text":"噬嗑：亨，利用狱。","vernacular":"《噬嗑卦》象征咬合：亨通无阻，有利于使用刑法。","image":"雷电，噬嗑；先王以明罚敕法。","imageVernacular":"《象辞》说：《噬嗑卦》的卦象是震（雷）下离（火）上，为雷电交击之表象。雷电交击，就像咬合一样；雷有威慑力，电能放光明，古代帝王效法这一现象，明其刑法，正其法令。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":21614,"endChar":22520,"startLine":862,"endLine":900},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%99%AC%E5%97%91&oldid=10645753&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(22,'山火贲','101001','中上卦','中上卦','艮','离','{"text":"贲：亨，小利，有攸往。","vernacular":"《贲卦》象征装饰：亨通，利于柔小者前去行事。","image":"山下有火，贲；君子以明庶政，无敢折狱。","imageVernacular":"《象辞》说：“《贲卦》的卦象是离（火）下艮（山）上，为山下燃烧着火焰之表象。山下火焰把山上草木万物照得通明，如同披彩，这就叫装饰。君子像火焰一样，使众多的政务清明，但却不能用修饰的方法来断官司。”"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":22520,"endChar":23404,"startLine":901,"endLine":939},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%B3%81&oldid=2405035&variant=zh-hans","patchIds":["edit-0021"]}');
INSERT INTO "hexagrams" VALUES(23,'山地剥','000001','中下卦','中下卦','艮','坤','{"text":"剥：不利有攸往。","vernacular":"《剥卦》象征剥落：不利于前去行事。","image":"山附于地，剥；上以厚下安宅。","imageVernacular":"《象辞》说：《剥卦》的卦象是坤（地）下艮（山）上，好比高山受侵蚀而风化，逐渐接近于地面之表象，因而象征剥落；位居在上的人看到这一现象，应当加强基础，使它更加厚实，只有这样才能巩固其住所而不至发生危险。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":23404,"endChar":24424,"startLine":940,"endLine":978},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%89%9D&oldid=10645800&variant=zh-hans","patchIds":["edit-0022"]}');
INSERT INTO "hexagrams" VALUES(24,'地雷复','100000','中中卦','中中卦','坤','震','{"text":"复：亨。出入无疾，朋来无咎。反复其道，七日来复。利有攸往。","vernacular":"《复卦》象征复归：亨通顺利。陽气从下面产生而逐渐向上行进没有阻碍，朋友前来也没有灾难危害。返回复归有一定的运动规律，经过七天就会前来复归。利于前去行事。","image":"“雷在地中，复；先王以至日闭关，商旅不行，后不省方。”","imageVernacular":"《象辞》说：《复卦》的卦象是震（雷）下坤（地）上，为雷在地中、陽气微弱地活动之表象，因而象征复归；从前的君主在陽气初生的冬至这一天关闭关口，使商人旅客停止活动，不外出经商、旅行，君主自己也不巡行视察四方。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":24424,"endChar":25572,"startLine":979,"endLine":1017},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%BE%A9&oldid=10643037&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(25,'天雷无妄','100111','下下卦','下下卦','乾','震','{"text":"无妄：元亨，利贞。其匪正有眚，不利有攸往。","vernacular":"《无妄卦》象征不妄动妄求：极为亨通顺利，利于坚守正道。然而，如果不能坚守正道的话就会发生祸殃，因而也就不利于前去行事了。","image":"天下雷行，物与无妄；先王以茂对时育万物。","imageVernacular":"《象辞》说：《无妄卦》的卦象是震（雷）下乾（天）上，好比在天的下面有雷在运行之表象，象征着天用雷的威势警戒万物，并赋予万物以不妄动妄求的本性；从前的君主顺应天命，尽其所能地遵循天时以养育万物的生长。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":25572,"endChar":26648,"startLine":1018,"endLine":1056},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%97%A0%E5%A6%84&oldid=10645038&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(26,'山天大畜','111001','中上卦','中上卦','艮','乾','{"text":"大畜：利贞；不家食吉，利涉大川。","vernacular":"《大畜卦》象征大量的畜养积聚：利于坚守正道；不要让贤能的人穷困地居于家中自谋生计，而应该把他招到朝廷中食取国家的俸禄，把才能贡献给国家，这样便可以获得吉祥；利于涉过大河。","image":"天在山中，大畜；君子以多识前言往行，以畜其德。","imageVernacular":"《象辞》说：《大畜卦》的卦象是乾（天）下艮（山）上，为天被包含在山里之表象，象征大量的畜养积聚；君子效法这一精神，应当努力更多地学习领会前代圣人君子的言论和行为，以此充实自己，培养美好的品德和积聚广博的知识。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":26648,"endChar":27773,"startLine":1057,"endLine":1095},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%A7%E7%95%9C&oldid=10646304&variant=zh-hans","patchIds":["edit-0023","edit-0024","edit-0025"]}');
INSERT INTO "hexagrams" VALUES(27,'山雷颐','100001','上上卦','上上卦','艮','震','{"text":"颐：贞吉；观颐，自求口实。","vernacular":"《颐卦》象征颐养：只有坚守正道才能获得吉祥；通过观察能够体现颐养的具体实例，以及自己是如何谋取口中食物的，这样才能真正地掌握颐养之道，获得吉祥。","image":"山下有雷，颐；君子以慎言语，节饮食。","imageVernacular":"《象辞》说：《颐卦》的卦象是震（雷）下艮（山）上，为雷在山下震动之表象，引申为咀嚼食物时上颚静止、下颚活动的状态，因而象征颐养；颐养必须坚守正道，所以君子应当言语谨慎以培养美好的品德，节制饮食以养育健康的身体。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":27773,"endChar":29008,"startLine":1096,"endLine":1134},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E9%A0%A4&oldid=10643091&variant=zh-hans","patchIds":["edit-0026"]}');
INSERT INTO "hexagrams" VALUES(28,'泽风大过','011110','中下卦','中下卦','兑','巽','{"text":"大过：栋桡；利有攸往，亨。","vernacular":"《大过卦》象征极为过分：房屋的栋梁受重压而弯曲；利于前去行事，亨通顺利。","image":"“泽灭木，大过；君子以独立不惧，遯世无闷。”","imageVernacular":"《象辞》说：“《大过卦》的卦象是巽（风）下兑（泽）上，巽在这里代表木，故为水泽淹没了树木之表象，象征极为过分；君子取法这一现象，就应当坚持自己的操守，进则超然独行，不必顾忌和畏惧他人的非议；退则逃避世间，不为隐姓埋名而苦闷烦恼。”"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":29008,"endChar":30092,"startLine":1135,"endLine":1173},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%A7%E9%81%8E&oldid=10645184&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(29,'坎为水','010010','下下卦','下下卦','坎','坎','{"text":"习坎：有孚，维心亨，行有尚。","vernacular":"《坎卦》象征重重艰险：像水奔流一样，胸怀坚定的信念，执著专一，内心才能不畏艰险而获得亨通，这种奔流不止、坚强刚毅的行为必然被人们所崇尚。","image":"水洊至，习坎；君子以常德行，习教事。","imageVernacular":"《象辞》说：《坎卦》的卦象是坎（水）下坎（水）上，为水流之表象。流水相继而至、潮涌而来，必须充满前方无数极深的陷坑才能继续向前，所以象征重重的艰险困难；君子因此应当坚持不懈地努力，反复不间断地推进教育事业。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":30092,"endChar":31166,"startLine":1174,"endLine":1212},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%9D%8E&oldid=10646381&variant=zh-hans","patchIds":["edit-0027"]}');
INSERT INTO "hexagrams" VALUES(30,'离为火','101101','中上卦','中上卦','离','离','{"text":"离：利贞，亨；畜牝牛，吉。","vernacular":"《离卦》象征附着：利于坚守正道，这样必然亨通；畜养柔顺的母牛，可以获得吉祥。","image":"“明两作，离；大人以继明照四方。”","imageVernacular":"《象辞》说：“《离卦》的卦象为离(火)下离(火)上，为光明接连升起之表象。《离卦》的本象为火，这里代表太陽。太陽东升西落，因而有上下充满光明的形象。太陽的光明连续照耀，必须高悬依附在天空才行，所以象征附着；伟大的人物效法这一现象，也应当连绵不断地用太陽般的光明美德普照四方。”"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":31166,"endChar":32277,"startLine":1213,"endLine":1251},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E9%9B%A2&oldid=10646424&variant=zh-hans","patchIds":["edit-0028","edit-0029"]}');
INSERT INTO "hexagrams" VALUES(31,'泽山咸','001110','中上卦','中上卦','兑','艮','{"text":"咸：亨，利贞；取女吉。","vernacular":"《咸卦》象征感应：亨通顺利，有利于坚守正道；娶妻可以获得吉祥。","image":"山上有泽，咸；君子以虚受人。","imageVernacular":"《象辞》说：《咸卦》的卦象是艮(山)下兑(泽)上，为山上有泽之表象，即上方的水泽滋润下面的山体，下面的山体承托上方的水泽并吸收其水分的形象，因而象征感应；君子效法山水相连这一现象，以虚怀若谷的精神容纳感化他人。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":32277,"endChar":33248,"startLine":1252,"endLine":1290},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%92%B8&oldid=10646450&variant=zh-hans","patchIds":["edit-0030"]}');
INSERT INTO "hexagrams" VALUES(32,'雷风恒','011100','中上卦','中上卦','震','巽','{"text":"恒：亨，无咎，利贞，利有攸往。","vernacular":"《恒卦》象征常久：亨通顺利，没有灾祸，利于坚守正道，利于前去行事。","image":"雷风，恒；君子以立不易方。","imageVernacular":"《象辞》说：《恒卦》的卦象是巽(风)下震(雷)上，为风雷交加之表象，二者常是相辅相成而不停地活动的形象，因而象征常久；君子效法这一现象，应当树立自身的形象，坚守常久不变的正道。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":33248,"endChar":34173,"startLine":1291,"endLine":1329},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%81%92&oldid=10646486&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(33,'天山遁','001111','下下卦','下下卦','乾','艮','{"text":"遯：亨，小利贞。","vernacular":"《遯卦》象征退避：亨通，小事能够成功。","image":"“天下有山，遯；君子以远小人，不恶而严。”","imageVernacular":"《象辞》说：《遯卦》的卦象是艮（山）下乾（天）上，为天下有山之表象，象征着隐让退避。因为山有多高，天就有多高，似乎山在逼天，而天在步步后退，但天无论怎样后退避让，却始终高踞在山之上。君子应同小人保持一定的距离，以傲然不可侵犯的态度截然划清彼此的界限，这样一来，就自然而然会生出一种震慑住小人的威严来。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":34173,"endChar":35257,"startLine":1330,"endLine":1368},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E9%81%AF&oldid=10645108&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(34,'雷天大壮','111100','中上卦','中上卦','震','乾','{"text":"大壮：利贞。","vernacular":"《大壮卦》象征十分强盛：坚守正道，将会非常有利。","image":"雷在天上，大壮；君子以非礼弗履。","imageVernacular":"《象辞》说：《大壮卦》的卦象是乾（天）下震（雷）上，为震雷响彻天上之表象，象征着十分强盛。君子应该严格要求自己，不要越出准则和规律去做非分之事。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":35257,"endChar":36284,"startLine":1369,"endLine":1407},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%A7%E5%A3%AF&oldid=10646529&variant=zh-hans","patchIds":["edit-0031"]}');
INSERT INTO "hexagrams" VALUES(35,'火地晋','000101','中上卦','中上卦','离','坤','{"text":"晋：康侯用锡马蕃庶，昼日三接。","vernacular":"《晋卦》象征长进：就像才干出众的公侯得到了天子的赏识，不仅赐给他许多车马，而且在一天之内多次接见他。","image":"明出地上，晋；君子以自昭明德。","imageVernacular":"《象辞》说：“陽光从地面上升起，象征着前进和昌盛，也象征着发出自己的光和热。所以，君子应该充分显示自己的才华和美德，发挥自己的作用。”"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":36284,"endChar":37436,"startLine":1408,"endLine":1446},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%99%89&oldid=10646579&variant=zh-hans","patchIds":["edit-0032","edit-0033"]}');
INSERT INTO "hexagrams" VALUES(36,'地火明夷','101000','中下卦','中下卦','坤','离','{"text":"明夷：利艰贞。","vernacular":"《明夷卦》象征光明受阻：在这种情况下，最好是在艰难困苦中坚守正道，保持自身的纯洁和善始善终的恒心。","image":"明入地中，“明夷”；君子以莅众，用晦而明。","imageVernacular":"《象辞》说：《明夷卦》的卦象是离（火）下坤（地）上，离为火，代表光明，为光明入地下之表象，象征着“光明被阻”。君子要能够遵循这个道理去管理民众，即有意不表露自己的才能和智慧，反而能在不知不觉中使民众得到治理。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":37436,"endChar":38520,"startLine":1447,"endLine":1485},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%98%8E%E5%A4%B7&oldid=10644507&variant=zh-hans","patchIds":["edit-0034"]}');
INSERT INTO "hexagrams" VALUES(37,'风火家人','101011','下下卦','下下卦','巽','离','{"text":"家人：利女贞。","vernacular":"《家人卦》象征家庭：特别注重女人在家中的作用，如果她能够坚守正道，始终如一，将会非常有利。","image":"风自火出，家人；君子以言有物而行有恒。","imageVernacular":"《象辞》说：《家人卦》的卦象是离（火）下巽（风）上，为风从火出之表象，象征着外部的风来自于本身的火，就像家庭的影响和作用都产生于自己内部一样。君子应该特别注意自己的一言一行，说话要有根据和内容，行动要有准则和规矩，不能朝三暮四和半途而废。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":38520,"endChar":39703,"startLine":1486,"endLine":1524},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%AE%B6%E4%BA%BA&oldid=2405005&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(38,'火泽睽','110101','下下卦','下下卦','离','兑','{"text":"睽：小事吉。","vernacular":"《睽卦》象征对立；小心谨慎地去行动做事，就能获得吉祥。","image":"上火下泽，睽；君子以同而异。","imageVernacular":"《象辞》说：《睽卦》的卦象是兑（泽）下离（火）上，为水火相遇之表象，象征对立。所以君子应该在求大同的前提下，保留小的差别和不同。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":39703,"endChar":40824,"startLine":1525,"endLine":1563},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E7%9D%BD&oldid=10646622&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(39,'水山蹇','001010','下下卦','下下卦','坎','艮','{"text":"蹇：利西南，不利东北；利见大人，贞吉。","vernacular":"《蹇卦》象征陷入困境，难以前进；面对这种情况，利于向西南行动，不利于向东北行动。此时利于出现大人物，只要能够坚守正道，始终如一，就一定可以获得吉祥。","image":"“山上有水，蹇；君子以反身修德。”","imageVernacular":"《象辞》说：《蹇卦》的卦象是艮（山）下坎（水）上，为高山上积水之表象，象征艰难险阻，行动困难。面对这种情况，君子应该很好地反省自己，提高自己的品德修养，以通过自身的努力渡过困境。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":40824,"endChar":41838,"startLine":1564,"endLine":1602},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%B9%87&oldid=2405036&variant=zh-hans","patchIds":["edit-0035"]}');
INSERT INTO "hexagrams" VALUES(40,'雷水解','010100','中上卦','中上卦','震','坎','{"text":"解：利西南；无所往，其来复吉；有攸往，夙吉。","vernacular":"《解卦》象征着灾祸危难的舒解：利于往西南方行事。如果没有什么灾祸，只要严守自己的本分和职责，就一定会吉祥如意的。但是如果发生了祸患，就应该及时地想办法加以解决，这样才能获得吉祥。","image":"雷雨作，解；君子以赦过宥罪。","imageVernacular":"《象辞》说：《解卦》的卦象是坎（水）下震（雷）上，坎又代表雨；为春雷阵阵，春雨潇潇，万物舒展生长之表象，充分显示了解卦所蕴含的解除危难的含义，因此，君子也应该勇于赦免那些有过错的，饶恕那些有罪过的，使他们在宽松的环境下，得到解脱和新生。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":41838,"endChar":42933,"startLine":1603,"endLine":1641},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%A7%A3&oldid=10646666&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(41,'山泽损','110001','下下卦','下下卦','艮','兑','{"text":"损：有孚，元吉，无咎，可贞，利有攸往。曷之用？二簋可用享。","vernacular":"《损卦》象征减损：内心有诚意，最为吉祥，不会招来祸患，可以坚守正道，利于前去行事。用什么祭祀神灵呢？两簋（古代盛食物的器具，圆口，有两个耳子）粗淡的食物就足够了。","image":"山下有泽，损；君子以惩忿窒欲。","imageVernacular":"《象辞》说：《损卦》的卦象是兑（泽）下艮（山）上，为山下有湖泽之表象，湖泽渐深而高山愈来愈高，象征着减损；按照这一现象中包含的哲理来做人，君子就应该抑制狂怒暴躁的脾性，杜绝世俗的欲望，也就是摒弃格调不高的低级趣味，不断培养高尚的品德。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":42933,"endChar":44351,"startLine":1642,"endLine":1680},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%90%8D&oldid=10646704&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(42,'风雷益','100011','上上卦','上上卦','巽','震','{"text":"益：利有攸往，利涉大川。","vernacular":"《益卦》象征增益：利于前去行事，利于渡大河越巨流。","image":"风雷，益；君子以见善则迁，有过则改。","imageVernacular":"《象辞》说：《益卦》的卦象是震（雷）下巽（风）上，为狂风和惊雷互相激荡，相得益彰之表象，象征“增益”的意思；从中得到的启示就是：君子应当看到良好的行为就马上向它看齐，有了过错就马上改正，不断增强自身的美好品德。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":44351,"endChar":45778,"startLine":1681,"endLine":1719},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E7%9B%8A&oldid=10646726&variant=zh-hans","patchIds":["edit-0036"]}');
INSERT INTO "hexagrams" VALUES(43,'泽天夬','111110','上上卦','上上卦','兑','乾','{"text":"夬：扬于王庭，孚号有厉；告自邑，不利即戎；利有攸往。","vernacular":"《夬卦》象征果决：在君王的宫廷之上当面宣扬小人的罪过，诚心实意地大声疾呼，告诫人们危险依然存在；告诉国人，不利于动用武力；利于马上前去有理有节地解决问题。","image":"泽上于天，夬；君子以施禄及下，居德则忌。","imageVernacular":"《象辞》说：《夬卦》的卦象是乾（天）下兑（泽）上，为湖水蒸发上天，即将化为雨倾注而下之表象，以此象征决断。君子从中得一启迪：应该自觉地向下层民众广施恩德，否则如果高高在上，不施恩德，就会遭到忌恨。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":45778,"endChar":47112,"startLine":1720,"endLine":1758},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%AC&oldid=2405003&variant=zh-hans","patchIds":["edit-0037"]}');
INSERT INTO "hexagrams" VALUES(44,'天风姤','011111','中卦','中中卦','乾','巽','{"text":"姤：女壮，勿用取女。","vernacular":"《姤卦》象征相遇：女子过分强壮，不适合娶来作妻子。","image":"“天下有风，姤；后以施命诰四方。”","imageVernacular":"《象辞》说：《姤卦》的卦象是巽（风）下乾（天）上，为天底下刮着风，风吹遍天地间各个角落，与万物相依之表象，象征着“相遇”；正如风吹拂大地的情形一样，君王也应该颁布政令通告四面八方。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":47112,"endChar":48151,"startLine":1759,"endLine":1797},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A7%A4&oldid=10646826&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(45,'泽地萃','000110','中上卦','中上卦','兑','坤','{"text":"萃：亨；王假有庙，利见大人，亨利贞，用大牲吉，利有攸往。","vernacular":"《萃卦》象征聚合：亨通；君王到宗庙里祭祀，祈求神灵保佑，利于出现德高望重的大人物，亨通无阻而且有利于树立纯正的道德风尚；用牛羊等大的祭品献祭能够带来吉祥如意，利于前去行事。","image":"“泽上于地，萃；君子以除戎器，戒不虞。”","imageVernacular":"《象辞》说：《萃卦》的卦象是：坤（地）下兑（泽）上，为地上有湖，四面八方的细流都源源不断汇入湖中之表象，象征着聚合；在这种众流会聚的时候，必然会出现鱼龙混杂、泥沙俱下的情况，因此君子应当修缮甲杖兵器，以防发生意想不到的变故。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":48151,"endChar":49407,"startLine":1798,"endLine":1836},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%90%83&oldid=10647546&variant=zh-hans","patchIds":["edit-0038"]}');
INSERT INTO "hexagrams" VALUES(46,'地风升','011000','上上卦','上上卦','坤','巽','{"text":"升：元亨，用见大人，勿恤，南征吉。","vernacular":"《升卦》象征上升：亨通，宜于出现权高位尊的大人物，用不着忧虑，向南方出征会带来吉祥。","image":"地中生木，升；君子以顺德，积小以高大。","imageVernacular":"《象辞》说：《升卦》的卦象是巽（风）下坤（地）上，而巽又象征高大树木，这样就成为地里边生长树木之表象。树木由矮小到高大，象征上升；与此相应，君子通过顺应自然规律来培养自己的品德，积累微小的进步来塑造高大完美的人格。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":49407,"endChar":50397,"startLine":1837,"endLine":1875},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%8D%87&oldid=10646879&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(47,'泽水困','010110','中上卦','中上卦','兑','坎','{"text":"困：亨；贞，大人吉，无咎；有言不信。","vernacular":"《困卦》象征困顿：亨通；占卜结果表明，神通广大的大人物可以获得吉祥，没有灾祸；此时许下的诺言很难令人相信。","image":"泽无水，困；君子以致命遂志。","imageVernacular":"《象辞》说：《困卦》的卦象是坎（水）下兑（泽）上，为泽中无水之表象，象征困顿；作为君子应该身处穷困而不气馁，为实现自己的志向，不惜牺牲生命。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":50397,"endChar":51811,"startLine":1876,"endLine":1914},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%9B%B0&oldid=10647032&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(48,'水风井','011010','上上卦','上上卦','坎','巽','{"text":"井：改邑不改井，无丧无得，往来井井。汔至亦未繘井，羸其瓶，凶。","vernacular":"《井卦》象征无穷：改变迁移城邑不会使水井发生改变和迁徙，井水不会枯竭也不会溢满，来来往往的人都到井里来打水。提水提到井口眼看就要上来了，却把水瓶打翻了，这是凶险的兆头。","image":"木上有水，井；君子以劳民劝相。","imageVernacular":"《象辞》说：《井卦》的卦象是巽（木）下坎（水）上，即是说水分沿着树身向上运行，直达树冠，为井水源源不断地被汲引到地面之表象，因此象征无穷；井水无穷无尽，孜孜不倦地养育着人们，君子应当效法这种美德，不辞劳苦地为大众谋福利，倡导助人为乐的社会风尚。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":51811,"endChar":53251,"startLine":1915,"endLine":1953},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E4%BA%95&oldid=10645240&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(49,'泽火革','101110','上上卦','上上卦','兑','离','{"text":"革：己日乃孚，元亨，利贞，悔亡。","vernacular":"《革卦》象征变革：在己日变革旧的事物，能够使民众深深的信服，前途通畅，坚守正道，最后就会取得成功，悔恨终将会消释。","image":"“泽中有火，革；君子以治历明时。”","imageVernacular":"《象辞》说：《革卦》的卦象是离（火）下兑（泽）上，为泽中有火之表象。大水可以使火熄灭；大火也可以使水蒸发，如此，水火相克相生，从而产生变革。君子根据变革的规律制定历法以明辨春、夏、秋、冬四季的变化。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":53251,"endChar":54257,"startLine":1954,"endLine":1992},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E9%9D%A9&oldid=10643173&variant=zh-hans","patchIds":["edit-0039"]}');
INSERT INTO "hexagrams" VALUES(50,'火风鼎','011101','中下卦','中下卦','离','巽','{"text":"鼎：元吉，亨。","vernacular":"《鼎卦》象征革故鼎新：十分吉祥，亨通。","image":"木上有火，鼎，君子以正位凝命。","imageVernacular":"《象辞》说：《鼎卦》的卦象是巽（木）下离（火）上，为木上燃着火之表象，是烹饪的象征，称为鼎；君子应当像鼎那样端正而稳重，以此完成使命。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":54257,"endChar":55218,"startLine":1993,"endLine":2031},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E9%BC%8E&oldid=10647086&variant=zh-hans","patchIds":["edit-0040","edit-0041"]}');
INSERT INTO "hexagrams" VALUES(51,'震为雷','100100','中上卦','中上卦','震','震','{"text":"震：亨。震来虩虩，笑言哑哑；震惊百里，不丧匕鬯。","vernacular":"《震卦》象征震动的雷声：可致亨通。当惊雷震动的时候，天下万物都感到恐惧，然而君子却能安之若素，言笑如故；即使雷声震惊百里之遥，主管祭祀的人却能做到从容不迫，手中的匙和酒都未失落。大丈夫威武不能屈，所以能成就大事。","image":"“洊雷，震；君子以恐惧修省。”","imageVernacular":"《象辞》说：《震卦》的卦象是震（雷）下震（雷）上，为雷相重叠之表象，好像震动的雷声；君子应悟知恐惧惊惕，修身省过。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":55218,"endChar":56355,"startLine":2032,"endLine":2070},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E9%9C%87&oldid=10644930&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(52,'艮为山','001001','中下卦','中下卦','艮','艮','{"text":"艮：艮其背，不获其身；行其庭，不见其人，无咎。","vernacular":"《艮卦》象征抑止：止于背部，不得使身体面向所止的地方；就好像在庭院里行走，两两相背，不曾感觉到有人的存在，进入这一境界，就不会受害。","image":"兼山，艮；君子以思不出其位。","imageVernacular":"《象辞》说：《艮卦》的卦象是艮（山）下艮（山）上，为两山重叠之表象，象征着抑止；君子的思想应当切合实际，不可超越自己所处的地位。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":56355,"endChar":57197,"startLine":2071,"endLine":2109},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%89%AE&oldid=10647135&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(53,'风山渐','001011','上上卦','上上卦','巽','艮','{"text":"渐：女归吉，利贞。","vernacular":"《渐卦》象征循序渐进：如同女子出嫁那样，按照一切婚嫁的礼节循序渐进，就会得到吉祥，有利于坚守正道。","image":"山上有木，渐；君子以居贤德善俗。","imageVernacular":"《象辞》说：《渐卦》的卦象是艮（山）下巽（风）上，表明高山上的树木逐渐长得高大，象征循序渐进；君子观看高山上的树木逐渐长得高大的情况，由是修养德性，改善社会的风尚、礼节和习惯。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":57197,"endChar":58260,"startLine":2110,"endLine":2148},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%BC%B8&oldid=2560535&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(54,'雷泽归妹','110100','下下卦','下下卦','震','兑','{"text":"归妹：征凶，无攸利。","vernacular":"《归妹卦》象征婚嫁：如果行为不正，前方会有凶险，不会有利益。","image":"“泽上有雷，归妹；君子以永终知敝。”","imageVernacular":"《象辞》说：《归妹卦》的卦象是兑（泽）下震（雷）上，兑又代表少女，震又代表长男为嫁出少女之表象；君子应当永远使夫妇和谐，白头偕老，防止夫妇关系被破坏。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":58260,"endChar":59172,"startLine":2149,"endLine":2187},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%AD%B8%E5%A6%B9&oldid=10647182&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(55,'雷火丰','101100','上上卦','上上卦','震','离','{"text":"丰：亨，王假之；勿忧，宜日中。","vernacular":"《丰卦》象征盛大丰满：亨通，君王能够使天下达到盛大丰满；就不用忧愁，好比太陽位居中天，光芒万丈。","image":"“雷电皆至，丰；君子以折狱致刑。”","imageVernacular":"《象辞》说：《丰卦》的卦象是离（火）下震（雷）上，离又代表闪电，震为雷，为雷电同时到来之表象，象征着盛大丰满；君子应该像雷电那样，审案用刑正大光明。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":59172,"endChar":60249,"startLine":2188,"endLine":2226},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%B1%90&oldid=10645290&variant=zh-hans","patchIds":["edit-0042"]}');
INSERT INTO "hexagrams" VALUES(56,'火山旅','001101','下下卦','下下卦','离','艮','{"text":"旅：小亨，旅贞吉。","vernacular":"《旅卦》象征旅行：小心谦顺可以亨通，旅行虽是小事，但能坚守正道必然吉祥。","image":"山上有火，旅；君子以明慎用刑，而不留狱。","imageVernacular":"《象辞》说：《旅卦》的卦象是艮（山）下离（火）上，为火势匆匆蔓延之表象，象征行旅之人匆匆赶路；君子观此应谨慎使用刑罚，明断决狱。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":60249,"endChar":61168,"startLine":2227,"endLine":2265},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%97%85&oldid=10647234&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(57,'巽为风','011011','中上卦','中上卦','巽','巽','{"text":"巽：小亨，利有攸往，利见大人。","vernacular":"《巽卦》象征顺从：谦虚柔顺，小心从事可以达到亨通，这样才能利于所要做的事情，利于出现有道德并居于高位的人物。","image":"“随风，巽；君子以申命行事。”","imageVernacular":"《象辞》说：《巽卦》的卦象是巽（风）下巽（风）上，为风行起来无所不入之表象，由此表示顺从。具有贤良公正美德的君主应当仿效风行而物无不顺的样子，下达命令，施行统治。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":61168,"endChar":62241,"startLine":2266,"endLine":2304},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%B7%BD&oldid=10644966&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(58,'兑为泽','110110','上上卦','上上卦','兑','兑','{"text":"兑：亨，利贞。","vernacular":"《兑卦》象征喜悦：亨通畅达，利于坚守中正之道。","image":"丽泽，兑；君子以朋友讲习。","imageVernacular":"《象辞》说：《兑卦》的卦象是兑（泽）下兑（泽）上，为两个泽水并连之表象。泽水相互流通滋润，彼此受益，因而又象征喜悦；君子应当效法这一精神，乐于同志同道合的朋友一道研讨学业，讲习道义，这是人生最大的乐趣。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":62241,"endChar":63042,"startLine":2305,"endLine":2343},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%85%8C&oldid=2404993&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(59,'风水涣','010011','下下卦','下下卦','巽','坎','{"text":"涣：亨，王假有庙，利涉大川，利贞。","vernacular":"《涣卦》象征涣散：顺畅亨通，贤明的君主去祠庙祭祀神灵以祈求保佑，利于渡过大川河流，利于坚守中正之道。","image":"风行水上，“涣”；先王以享于帝立庙。","imageVernacular":"《象辞》说：《涣卦》的卦象是坎（水）下巽（风）上，为风行水上之表象，象征涣散、离散。先代君王为了收合归拢人心便祭祀天帝，修建庙宇。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":63042,"endChar":63906,"startLine":2344,"endLine":2382},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%B8%99&oldid=10647580&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(60,'水泽节','110010','上上卦','上上卦','坎','兑','{"text":"节：亨，苦节不可，贞。","vernacular":"《节卦》象征节制：节制可致亨通；但过分的节制也不可以的，应当持正、适中。","image":"泽上有水，节；君子以制数度，议德行。","imageVernacular":"《象辞》说：《节卦》的卦象是兑（泽）下坎（水）上，为泽上有水之表象，象征以堤防来节制。水在泽中，一旦满了就溢出来，而堤防本身就是用来节制水的盈虚的。君子应当效法《节卦》的义理，制定典章制度和必要的礼仪法度来作为行事的准则，以此来节制人们的行为。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":63906,"endChar":64742,"startLine":2383,"endLine":2421},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E7%AF%80&oldid=2405027&variant=zh-hans","patchIds":["edit-0043"]}');
INSERT INTO "hexagrams" VALUES(61,'风泽中孚','110011','下下卦','下下卦','巽','兑','{"text":"中孚：豚鱼吉，利涉大川，利贞。","vernacular":"《中孚卦》象征诚信：诚信施及到愚钝无知的小猪小鱼身上，从而感化了它们，因此获得吉祥，利于涉越大河大川，利于坚守中正之道。","image":"“泽上有风，中孚；君子以议狱缓死。”","imageVernacular":"《象辞》说《中孚卦》的卦象是兑（泽）下巽（风）上，为泽上有风，风吹动着泽水之表象，比喻没有诚信之德施及不到的地方，说明极为诚信；君子应当效法“中孚”之象，广施信德，慎重地议论刑法讼狱，宽缓死刑。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":64742,"endChar":65737,"startLine":2422,"endLine":2460},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E4%B8%AD%E5%AD%9A&oldid=10647425&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(62,'雷山小过','001100','中上卦','中上卦','震','艮','{"text":"小过：亨，利贞；可小事，不可大事，飞鸟遗之音，不宜上，宜下，大吉。","vernacular":"《小过卦》象征略为过分：小过之时，可致亨通，但应以正为本，故而利于坚守中正之道；可以去干一些小事，但不可去涉足一些大事；飞鸟留下悲鸣之时，不应该向上强飞，而应该向下栖息，如此，大为吉祥。","image":"山上有雷，小过；君子以行过乎恭，丧过乎哀，用过乎俭。","imageVernacular":"《象辞》说：《小过卦》的卦象是艮（山）下震（雷）上，为山上响雷之表象，雷声超过了寻常的雷鸣，以此比喻“小有过越”，君子应效法“小过”之象，在一些寻常小事上能略有过分，如行止时过分恭敬，遇到丧事时过分悲哀，日常用度过分节俭，为的是矫枉过正。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":65737,"endChar":66835,"startLine":2461,"endLine":2499},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%B0%8F%E9%81%8E&oldid=10643238&variant=zh-hans","patchIds":[]}');
INSERT INTO "hexagrams" VALUES(63,'水火既济','101010','中上卦','中上卦','坎','离','{"text":"既济：亨小，利贞；初吉终乱。","vernacular":"《既济卦》象征成功：此时功德完满，连柔小者都亨通顺利，有利于坚守正道；开始时是吉祥的，但如有不慎，终久必导致混乱。","image":"“水在火上，既济；君子以思患而预防之。”","imageVernacular":"《象辞》说：《既济卦》的卦象是离（火）下坎（水）上，为水在火上之表象，比喻用火煮食物，食物已熟，象征事情已经成功；君子应有远大的目光，在事情成功之后，就要考虑将来可能出现的种种弊端，防患于未然，采取预防措施。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":66835,"endChar":67928,"startLine":2500,"endLine":2538},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%97%A2%E6%BF%9F&oldid=2572417&variant=zh-hans","patchIds":["edit-0044","edit-0045","edit-0046"]}');
INSERT INTO "hexagrams" VALUES(64,'火水未济','010101','中下卦','中下卦','离','坎','{"text":"未济：亨；小狐汔济，濡其尾，无攸利。","vernacular":"《未济卦》象征事未完成：经过努力可以得到亨通；小狐狸渡河快到对岸了，却浸湿了尾巴，则没有什么吉利。","image":"火在水上，未济；君子以慎辨物居方。","imageVernacular":"《象辞》说：《未济卦》的卦象是坎（水）下离（火）上，为火在水上之表象。火在水上，大火燃烧，水波浩浩，水火相对相克，象征着未完成；君子此时要明辨各种事物，看到事物的本质，努力使事物的变化趋向好的方面，这样做则万事可成。"}','{"sourceRef":{"sourceId":"user-yijing64","startChar":67928,"endChar":68987,"startLine":2539,"endLine":2575},"referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%9C%AA%E6%BF%9F&oldid=10647450&variant=zh-hans","patchIds":[]}');
