INSERT INTO "line_details" VALUES(2,5,8,'{"polarity":"yin","positionType":"yang","correctPosition":false,"central":true,"respondingPosition":2,"oppositeResponse":false}','[{"text":"六五以“黄裳，元吉”说明内在中顺之德，不以六四“括囊”代替本爻。黄为中色，裳在下，传统解读重在居中而谦下。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":2,"referenceId":"zhouyi-02","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%9D%A4&oldid=2404999&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
