INSERT INTO "line_details" VALUES(3,4,17,'{"polarity":"yin","positionType":"yin","correctPosition":true,"central":false,"respondingPosition":1,"oppositeResponse":true}','[{"text":"六四以求婚与相合为象。小象“求而往，明也”强调主动寻求适当联系；这与六三没有引导而逐鹿的情境不同。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":3,"referenceId":"zhouyi-03","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%B1%AF&oldid=10643482&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
