INSERT INTO "line_details" VALUES(4,2,23,'{"polarity":"yang","positionType":"yin","correctPosition":false,"central":true,"respondingPosition":5,"oppositeResponse":true}','[{"text":"九二位于本卦第2爻，阳爻；单爻变化得到第23卦山地剥。爻义请结合本爻经文、小象与白话阅读。","kind":"computed-structural-note","evidence":{"hexagramId":4,"referenceId":"zhouyi-04","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%92%99&oldid=10645379&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
