INSERT INTO "line_details" VALUES(4,5,59,'{"polarity":"yin","positionType":"yang","correctPosition":false,"central":true,"respondingPosition":2,"oppositeResponse":true}','[{"text":"六五“童蒙，吉”，小象以“顺以巽也”说明虚心受教的态度。这里不是上九“利用御寇”的警戒之义。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":4,"referenceId":"zhouyi-04","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%92%99&oldid=10645379&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
