INSERT INTO "line_details" VALUES(8,4,45,'{"polarity":"yin","positionType":"yin","correctPosition":true,"central":false,"respondingPosition":1,"oppositeResponse":false}','[{"text":"六四“外比之，贞吉”，小象以“以从上也”说明向外亲比、守正相从；不能以六三“比之匪人”代替本爻。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":8,"referenceId":"zhouyi-08","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E6%AF%94&oldid=10645543&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
