INSERT INTO "line_details" VALUES(14,1,50,'{"polarity":"yang","positionType":"yang","correctPosition":true,"central":false,"respondingPosition":4,"oppositeResponse":false}','[{"text":"初九处大有之初，以不交于害、保持艰慎为要。尚未承担重任时，也不应因处境富足而放松戒惧。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":14,"referenceId":"zhouyi-14","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%A7%E6%9C%89&oldid=10645712&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(14,2,30,'{"polarity":"yang","positionType":"yin","correctPosition":false,"central":true,"respondingPosition":5,"oppositeResponse":true}','[{"text":"九二“大车以载”，小象“积中不败也”，借能承载之车说明内有积蓄、能够担当。重点是充实能力与谨慎任事。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":14,"referenceId":"zhouyi-14","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%A7%E6%9C%89&oldid=10645712&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(14,3,38,'{"polarity":"yang","positionType":"yang","correctPosition":true,"central":false,"respondingPosition":6,"oppositeResponse":false}','[{"text":"九三“公用亨于天子，小人弗克”，用朝享之礼说明有德者能够承担相应礼遇，小人则难以胜任。亨字的通读需结合所据注本。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":14,"referenceId":"zhouyi-14","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%A7%E6%9C%89&oldid=10645712&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(14,4,26,'{"polarity":"yang","positionType":"yin","correctPosition":false,"central":false,"respondingPosition":1,"oppositeResponse":false}','[{"text":"九四“匪其彭，无咎”，小象强调明辨。处在富盛之时能辨轻重、不自夸其盛，是这条爻辞的一种传统读法。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":14,"referenceId":"zhouyi-14","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%A7%E6%9C%89&oldid=10645712&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(14,5,1,'{"polarity":"yin","positionType":"yang","correctPosition":false,"central":true,"respondingPosition":2,"oppositeResponse":true}','[{"text":"六五以诚信相交而有威仪，既不失亲和，也有使人敬重的分寸。小象“信以发志”与“易而无备”应结合阅读。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":14,"referenceId":"zhouyi-14","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%A7%E6%9C%89&oldid=10645712&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(14,6,34,'{"polarity":"yang","positionType":"yin","correctPosition":false,"central":false,"respondingPosition":3,"oppositeResponse":false}','[{"text":"上九“自天佑之，吉无不利”，小象“上吉大有祐也”。传统读法重视顺道、守信与尚贤，不把这句话改写为现实收益的保证。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":14,"referenceId":"zhouyi-14","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%A4%A7%E6%9C%89&oldid=10645712&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(15,1,36,'{"polarity":"yin","positionType":"yang","correctPosition":false,"central":false,"respondingPosition":4,"oppositeResponse":false}','[{"text":"初六“谦谦君子”，小象“卑以自牧也”，强调谦下并以此自我修养。涉大川的象意须与这种品德条件一起理解。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":15,"referenceId":"zhouyi-15","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%AC%99&oldid=2106142&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(15,2,46,'{"polarity":"yin","positionType":"yin","correctPosition":true,"central":true,"respondingPosition":5,"oppositeResponse":false}','[{"text":"六二“鸣谦，贞吉”，小象“中心得也”，重在内心确有谦德而自然表现于外，不是只求谦逊的名声。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":15,"referenceId":"zhouyi-15","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%AC%99&oldid=2106142&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(15,3,2,'{"polarity":"yang","positionType":"yang","correctPosition":true,"central":false,"respondingPosition":6,"oppositeResponse":true}','[{"text":"九三“劳谦君子”，有功劳而不自矜；小象“万民服也”将众人信服与这种品德联系起来。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":15,"referenceId":"zhouyi-15","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%AC%99&oldid=2106142&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(15,4,62,'{"polarity":"yin","positionType":"yin","correctPosition":true,"central":false,"respondingPosition":1,"oppositeResponse":false}','[{"text":"六四“撝谦”，小象“不违则也”，强调施行谦道而不违准则。这里不是大有九四关于富盛的爻辞。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":15,"referenceId":"zhouyi-15","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%AC%99&oldid=2106142&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(15,5,39,'{"polarity":"yin","positionType":"yang","correctPosition":false,"central":true,"respondingPosition":2,"oppositeResponse":false}','[{"text":"六五“不富以其邻，利用侵伐”，说明谦道并非放弃原则；小象“征不服也”应放在古代秩序与征伐语境中理解。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":15,"referenceId":"zhouyi-15","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%AC%99&oldid=2106142&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
INSERT INTO "line_details" VALUES(15,6,52,'{"polarity":"yin","positionType":"yin","correctPosition":true,"central":false,"respondingPosition":3,"oppositeResponse":true}','[{"text":"上六“鸣谦，利用行师，征邑国”，与志愿未遂、整治自身所属的古代政治语境相连，不是“大有上九”的天佑之辞。","kind":"new-editorial-paraphrase","evidence":{"hexagramId":15,"referenceId":"zhouyi-15","url":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E8%AC%99&oldid=2106142&variant=zh-hans","structuralRule":"六爻由下至上；奇位阳位、偶位阴位；单动爻只翻转该位"}}]');
