INSERT INTO "special_lines" VALUES(1,'用九','{"text":"见群龙无首，吉。","vernacular":"用九，出现群龙也不愿意为首的现象，是很吉利的。","image":"“用九”，天德不可为首也。","imageVernacular":"《象辞》说：“用九”的爻象说明，天虽生万物，但却不居首、不居功。","id":"hex-01-用九","label":"用九","position":null,"sourceRef":{"sourceId":"user-yijing64","startChar":1361,"endChar":1459,"startLine":112,"endLine":117},"referenceId":"zhouyi-01","referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E4%B9%BE&oldid=2404991&variant=zh-hans"}');
INSERT INTO "special_lines" VALUES(2,'用六','{"text":"利永贞。","vernacular":"“用六”这一爻，利于永远保持中正。","image":"用六“永贞”，以大终也。","imageVernacular":"《象辞》说：用六的爻辞说“利于永远保持中正”，即是指陰盛到了极点就会向陽转化。","id":"hex-02-用六","label":"用六","position":null,"sourceRef":{"sourceId":"user-yijing64","startChar":2414,"endChar":2508,"startLine":156,"endLine":161},"referenceId":"zhouyi-02","referenceUrl":"https://zh.wikisource.org/w/index.php?title=%E5%91%A8%E6%98%93%2F%E5%9D%A4&oldid=2404999&variant=zh-hans"}');
INSERT INTO "void_narrative_rules" VALUES('true_void','依现有证据已判真空，后遇填实或冲实也不自动恢复，不能把一个时间节点当成落实保证','["user-void-extension","user-void-timing"]');
INSERT INTO "void_narrative_rules" VALUES('dormant','眼下有静空待实的意味，进程容易悬而未落，适合等实际条件与填实、冲实节点相互印证','["user-void-extension","user-void-timing"]');
INSERT INTO "void_narrative_rules" VALUES('moving_exempt','虽有逢空的象意，本身仍在发动，保留生克作用；过程中可能反复，需看实际推进','["user-void-extension","user-void-timing"]');
INSERT INTO "void_narrative_rules" VALUES('strong_exempt','虽有逢空的象意，仍因得令保留作用，不能把它直接看作失去力量','["user-void-extension","user-void-timing"]');
INSERT INTO "void_narrative_rules" VALUES('supported','有明确生扶，按假空待落实看，适合观察帮助是否化为实际承接','["user-void-extension","user-void-timing"]');
INSERT INTO "void_narrative_rules" VALUES('partial_pending','有一部分对应条件尚悬，依据还不足以判定整股力量失效','["user-void-extension","user-void-timing"]');
INSERT INTO "void_narrative_rules" VALUES('partial_not_applied','只部分命中，依当前全支规则保留作用，仍需核对悬而未定的一面','["user-void-extension","user-void-timing"]');
INSERT INTO "void_narrative_rules" VALUES('released','已提供填实或合规释放条件，需再与实际进展核对，不能只凭节点认定事情完成','["user-void-extension","user-void-timing"]');
