PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
PRAGMA defer_foreign_keys=ON;
CREATE TABLE classical_cases(id TEXT PRIMARY KEY,title TEXT NOT NULL,record_json TEXT NOT NULL,usage TEXT NOT NULL CHECK(usage='historical-source-report;not-new-user-prediction'));
CREATE TABLE domain_narrative_rules(domain_id TEXT PRIMARY KEY REFERENCES domains(id),rules_json TEXT NOT NULL);
CREATE TABLE domains(id TEXT PRIMARY KEY,title TEXT NOT NULL,text TEXT NOT NULL,source_json TEXT NOT NULL,usage TEXT NOT NULL DEFAULT 'historical-reference-not-proven-outcome');
CREATE TABLE hexagrams(id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 64),name TEXT NOT NULL UNIQUE,bits_bottom_up TEXT NOT NULL UNIQUE CHECK(length(bits_bottom_up)=6 AND bits_bottom_up NOT GLOB '*[^01]*'),display_grade TEXT NOT NULL CHECK(display_grade IN ('上上卦','中上卦','中中卦','中下卦','下下卦','中卦')),canonical_grade TEXT NOT NULL CHECK(canonical_grade IN ('上上卦','中上卦','中中卦','中下卦','下下卦')),upper_trigram TEXT NOT NULL,lower_trigram TEXT NOT NULL,reading_json TEXT NOT NULL,provenance_json TEXT NOT NULL);
CREATE TABLE line_details(hexagram_id INTEGER NOT NULL,position INTEGER NOT NULL,changed_hexagram_id INTEGER NOT NULL REFERENCES hexagrams(id),structure_json TEXT NOT NULL,editorial_notes_json TEXT NOT NULL,PRIMARY KEY(hexagram_id,position),FOREIGN KEY(hexagram_id,position) REFERENCES lines(hexagram_id,position));
CREATE TABLE lines(hexagram_id INTEGER NOT NULL REFERENCES hexagrams(id),position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 6),label TEXT NOT NULL,text TEXT NOT NULL,vernacular TEXT NOT NULL,image TEXT NOT NULL,image_vernacular TEXT NOT NULL,source_json TEXT NOT NULL,PRIMARY KEY(hexagram_id,position));
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE month_orders(id TEXT PRIMARY KEY,label TEXT NOT NULL,season TEXT NOT NULL,definition_json TEXT NOT NULL);
CREATE TABLE monthly_narratives(id TEXT PRIMARY KEY,hexagram_id INTEGER NOT NULL,moving_line INTEGER NOT NULL,month_order_id TEXT NOT NULL REFERENCES month_orders(id),mutual_hexagram_id INTEGER NOT NULL REFERENCES hexagrams(id),changed_hexagram_id INTEGER NOT NULL REFERENCES hexagrams(id),paragraphs_json TEXT NOT NULL,trace_json TEXT NOT NULL,UNIQUE(hexagram_id,moving_line,month_order_id),FOREIGN KEY(hexagram_id,moving_line) REFERENCES lines(hexagram_id,position));
CREATE TABLE reference_commentary_links(hexagram_id INTEGER PRIMARY KEY REFERENCES hexagrams(id),path TEXT NOT NULL,usage TEXT NOT NULL CHECK(usage='explicit-reference-only;body-excluded'));
CREATE TABLE rule_profiles(id TEXT PRIMARY KEY,profile_json TEXT NOT NULL);
CREATE TABLE source_documents(id TEXT PRIMARY KEY,path TEXT NOT NULL,sha256 TEXT NOT NULL,metadata_json TEXT NOT NULL);
CREATE TABLE special_lines(hexagram_id INTEGER PRIMARY KEY REFERENCES hexagrams(id),label TEXT NOT NULL CHECK(label IN ('用九','用六')),reading_json TEXT NOT NULL,CHECK((hexagram_id=1 AND label='用九') OR (hexagram_id=2 AND label='用六')));
CREATE TABLE void_narrative_rules(state TEXT PRIMARY KEY,text TEXT NOT NULL,source_ids_json TEXT NOT NULL);
凡占天时，不分体用，全观诸卦，详推五行。离多主晴，坎多主雨，坤乃陰晦，乾主晴明，震多则春夏雷轰，巽多则四时风烈，艮多则久雨必晴，兑多则不雨亦陰。夏占离多而无坎，则亢旱炎炎。冬占坎多而无离，则雨雪飘飘。
全观诸卦者，谓互变卦。五行属离属火，主晴；坎为水，主雨；坤为地气，主陰；乾为天，主晴明；震为雷，巽为风，秋冬震多无制，亦有非常之雷，有巽佐之，则为风撼雷动之应；艮为山云之气，若雨久，得艮则当止。艮者，止也，亦土克水之义。兑为泽，故不雨亦陰。夫以造化之辨固难测，理数之妙亦可凭，是以乾象乎天，四时晴明；坤体乎地，一气惨然。乾、坤两同，晴雨时变。坤、艮两并，陰晦不常。卜数有陽有陰，卦象有奇有偶。陰雨陽晴，奇偶暗重。坤为老陰之极，久晴必雨；乾为老陽之极，久雨必晴。若逢重坎重离，亦日时晴时雨。坎为水，必雨；离为火，必晴。乾、兑为金，秋明晴；坎之水，冬雪凛冽；坤、艮之土，春雨泽，夏火炎蒸。《易》曰：“云从龙，风从虎”。又曰：“艮为云，巽为风。”艮、巽重逢，风云际会，飞沙走石，蔽日藏山，不以四时，不必二用。坎在艮上，布雾兴云，若在兑上，凝霜作雪。乾、兑为霜雪雹霰，离火为日电虹霓。离为电，震为雷，重会而雷电俱作。坎为雨，巽为风，相逢而风雨骤兴。震卦重逢，雷惊百里。坎爻叠见，润泽九垓。故卦体之两逢，亦爻象之总断。地天泰，水天需，昏蒙之象。天地否，水地比，黑暗之形。爻纯离，夏必旱，四季皆晴。爻纯坎，冬必寒，四时必雨。久雨不晴，逢艮必止。久晴不雨，得此亦然。又若水火既济、火水未济，四时不测风云；风泽中孚，泽风大过，三冬必然雨雪。水山蹇，山水蒙，百步必须执盖。地风升，风地观，四时不可行船。离在艮上，暮雨朝晴，离互艮宫，暮晴朝雨。巽、坎互离，虹霞乃见，巽、离互坎，造化亦同。又须推测四时，不可执迷一理。震、离为电、为雷，应在夏天，乾、兑为霜、为雪，验于冬月。天地之理大矣哉！得斯文者，当敬宝之。

','{"sourceId":"user-meihua","startChar":15052,"endChar":15857,"startLine":516,"endLine":519}','historical-reference-not-proven-outcome');
人事之占，详观体用。体卦为主，用卦为宾。用克体不宜，体克用则吉。用生体有进益之喜，体生用有耗失之患。体用比和，谋为吉利。更详观互卦、变卦，以断吉凶；复究盛衰，以明休咎。
人事之占，则以全体用总章向决吉凶。若有生体之卦，即看前章八卦中生体之卦有何吉；又看克体之卦有何凶，即看前章克体之卦。无生克，止断本卦。

','{"sourceId":"user-meihua","startChar":15857,"endChar":16019,"startLine":520,"endLine":523}','historical-reference-not-proven-outcome');
凡占家宅，以体为主，用为家宅。体克用，则家宅多吉，用克体，则家宅多凶。体生用，多耗散，或防失盗之忧。用生体，多进益，或有馈送之喜。体用比和，家宅安稳。如有生体之卦，即以前章人事占断之。

','{"sourceId":"user-meihua","startChar":16019,"endChar":16121,"startLine":524,"endLine":526}','historical-reference-not-proven-outcome');
凡占屋舍，以体为主，用为屋舍。体克用，居之吉，用克体，居之凶。体生用，主资财衰退；用生体，则门户兴隆。体用比和，自然安稳。

','{"sourceId":"user-meihua","startChar":16121,"endChar":16192,"startLine":527,"endLine":529}','historical-reference-not-proven-outcome');
占婚姻以体为主，用为婚姻。用生体，婚易成，或因婚有得；体生用，婚难成，或因婚有失。体克用，可成但成之迟；用克体，不可成，成亦有害。体用比和，婚姻吉利。
占婚，体为所占之家，用为所婚之家。体卦旺，则此家门户胜；用卦旺，则彼家资盛。生体，则得婚姻之财；或彼有相就之意；体生，则无嫁奁之资，或此去求婚方谐。若体用比和，则彼此相就，良配无疑。
乾：端正而长
坎：邪婬、黑色、嫉妒、奢侈
艮：色黄多巧
震：美貌难犯
巽：发少稀疏，丑陋心贪
离：短赤色，性不常
坤：貌丑，大腹而黄
兑：高长，语话喜悦，白色

','{"sourceId":"user-meihua","startChar":16192,"endChar":16449,"startLine":530,"endLine":541}','historical-reference-not-proven-outcome');
占生产，以体为母，用为生。体用俱宜乘旺，不宜乘衰。宜相生，不宜相克。体克用不利于子；用克体不利于母。体克用而用卦衰，则子难完；用克体而体卦衰，则母难保。用生体，利于母；体生用，利于子。体用比和，生育顺快。若欲辨其男女，当于前卦审之。陽卦陽爻多者则生男，陰卦陰爻多者生女。陰陽卦爻相生，则察所占左右人之奇偶以证之。如欲决其日辰，则以用卦之气数参决之。所谓卦之气数者，即看何为用卦，于八卦时序之类次之。

','{"sourceId":"user-meihua","startChar":16449,"endChar":16658,"startLine":542,"endLine":544}','historical-reference-not-proven-outcome');
凡占饮食，以体为主，用为饮食。用生体，饮食必丰；体生用，饮食难就。体克用，则饮食有阻；用克体，饮食必无。体用比和，饮食丰足。又卦中有坎则有酒，有兑则有食。无坎无兑，则皆无。兑、坎生体，酒肉醉饱。欲知所食何物，以饮食推之。欲知席上何人，以互卦人事推之。
饮食人事类者，即前八卦内万物属类是也。

','{"sourceId":"user-meihua","startChar":16658,"endChar":16813,"startLine":545,"endLine":548}','historical-reference-not-proven-outcome');
占求谋，以体为主，用为所谋之事。体克用，谋虽可成，但成迟。用克体，求谋不成，谋亦有害。用生体。不谋而成；体生用，多谋少遂。体用比和，求谋称意。

','{"sourceId":"user-meihua","startChar":16813,"endChar":16894,"startLine":549,"endLine":551}','historical-reference-not-proven-outcome');
凡占求名，以体为主，用为名。体克用，名可成，但成迟。用克体，名不可成。体生用，名不可就，或因名有丧。用生体，名易成，或因名有得。体用比和，功名称意。欲知名成之日，生体之卦气详之。欲知职任之处，变卦之方道决之。若无克体之卦，则名易就，止看卦体时序之类，以定日期。若在任占卜，最忌见克体之卦，如卦有克体者，即居官见祸，轻则上司责罚，重则削官退居。其日期，看克体之卦气者，于八卦所属时序类中断之。

','{"sourceId":"user-meihua","startChar":16894,"endChar":17099,"startLine":552,"endLine":554}','historical-reference-not-proven-outcome');
占求财，以体为主，以用为财。体克用，有财；用克体，无财。体生用，财有损耗之忧；用生体，财有进益之喜。体用比和，财利快意。欲知得财之日，生体之卦气定之。欲知破财之日，克体卦气定之。
又若卦中有体克用之卦，及生体之卦，则有财，此卦气即见财之日。若卦中有克体之卦，及体生用之卦，即破财，此卦气破财之日。

','{"sourceId":"user-meihua","startChar":17099,"endChar":17257,"startLine":555,"endLine":558}','historical-reference-not-proven-outcome');
占交易，以体为主，用为财。体克用，有财；用克体，不成。体生用，难成，或因交易有失。用生体，即成，成必有财。体用比和，易成。

','{"sourceId":"user-meihua","startChar":17257,"endChar":17329,"startLine":559,"endLine":561}','historical-reference-not-proven-outcome');
占出行，以体为主，用为所行之应。体克用，可行，所至多得意。用克体，出则有祸。体生用，出行有破耗之失；用生体，有意外之财。体用比和，出行顺快。
又凡出行，体宜乘旺，诸卦宜生体。体卦乾、震多，主动。坤、艮多，不动。巽宜舟行，离宜陆行。坎妨失脱，兑主纷争。

','{"sourceId":"user-meihua","startChar":17329,"endChar":17465,"startLine":562,"endLine":565}','historical-reference-not-proven-outcome');
占行人，以体为主，用为行人。体克用，行人归迟；用克体，行人不归。体生用，行人未归；用生体，行人即归。体用比和，归期不日矣。
又以用卦看行人在外之情况。逢生，在外顺快；逢衰受克，在外灾殃。震多不宁，艮多有阻。坎有险难，兑主纷争。

','{"sourceId":"user-meihua","startChar":17465,"endChar":17589,"startLine":566,"endLine":569}','historical-reference-not-proven-outcome');
占谒见，以体为主，用为所见之人。体克用，可见；用克体，不见。体生用，难见，见之而无益；用生体，可见，见之且有得。体用比和，欢然相见。

','{"sourceId":"user-meihua","startChar":17589,"endChar":17666,"startLine":570,"endLine":572}','historical-reference-not-proven-outcome');
占失物，以体为主，用为失物。体克用，可寻迟得；用克体，不可寻。体生用，物难见；用生体，物易寻。体用比和，物不失矣。
又以变卦为失物之所在。如变是乾，则觅于西北或公榭楼阁之所，或金石之傍，或圆器之中，或高亢之地。变卦是坤，则觅于西南方，或田野之所，或仓禀之处，或稼穑之处，或土窖穴藏之所，或瓦器方器之中。震则寻于东方，或山林之所，或丛棘之内，钟鼓之傍，或闹市之地，或大途之所。巽则寻于东南方，或山林之所，或寺观之地，或菜蔬之园，或舟居之间，或木器之内。坎则寻于北方，多藏于水边或溪井沟渠之处，或酒醋之边，或鱼盐之地。离则寻于南方，或疱厨之间，或炉冶之傍，或在明窗，或遗虚室，或在文书之侧，或在烟火之地。艮则寻于东北方，或山林之内，或近路边，或岩石傍，或藏土穴。兑则寻于西方，或居泽畔，或败垣破壁之内，或废井缺沼之中。

','{"sourceId":"user-meihua","startChar":17666,"endChar":18034,"startLine":573,"endLine":576}','historical-reference-not-proven-outcome');
凡占疾病，以体为病人，用为病症。体卦宜旺不宜衰，体宜逢生，不宜见克。用宜生体，不宜克体。体克用，病易安；体生用，病难愈。体克用者，勿药有喜；用克体者，虽药无功。若体逢克而乘旺，犹为庶几。体遇克而更衰，断无存日。欲知凶中有救，生体之卦存焉。体生用者，迁延难好；用生体者，即愈。体用比和，疾病易安。若究和平之日，主卦决之。若详危厄之期，克体之卦定之。若论医药之属，当看生体之卦。如离卦生体，宜服热药；坎卦生体，宜服冷药，如艮温补；乾、兑凉药是也。
又有信鬼神之说，虽非《易》道，然不可谓《易》道之不该。姑以理推之。如卦有克体者，即可测其鬼神。乾卦克体，主有西北方之神，或兵刀之鬼，或天行时气，或乘正之邪神。坤则西南之神，或旷野之鬼，或连亲之鬼，或水土里社之神，或犯方隅，或无主之祟。震则东方之神，或木下之神，或妖怪百端，或影响时见。巽则东南之鬼，或自缢戕生，或枷锁致命。坎则北方之鬼，或水旁之神，或没溺而亡，或血疾之鬼。离则南方之鬼，或猛勇之神，或犯灶司，或得衍于香火，或焚烧之鬼。或遇热病而亡。艮则东北之神，或是山林之祟，或山魈木客，或土怪石精。兑则西方之神，或阵亡之鬼，或废疾之鬼，或刎颈戕生之鬼。卦中无克体之卦者，不必论之。
又问乾上坤下，占病如何断，尧夫曰：“乾上坤下第一爻动，便是生体之义。变为震木，互见巽艮，俱是生成之义，是谓不灾，逢生之日即愈。”
又问：“第二爻动如何？”曰：“是变为坎水，乃泄体败金之义。金入水乡，互见巽、离，乃为风火扇炉，俱为克体之义。更看占时外应如何，即为焚尸之象，断之死无疑矣。以春夏秋冬四季推之，更见详理。”又曰：“第三爻动，坤变艮土，俱在生体之义，不问互卦，亦断其吉无疑。”又曰：“第四爻动，乾变巽木，金木俱有克体之义，互吉亦凶。木有扛尸之义，金为砖椁之推。是必定之推，必定之理。”又曰：“第五爻动，乾变离，反能生体，互变俱生体，是其吉无疑。更有吉兆则愈吉。其断明矣。”又曰：“第六爻动，乾变兑，则能泄体，互见巽、艮，一凶一吉，其病非死必危。亦宜看兆吉凶，吉则言吉，凶则言凶。此断甚明。余卦皆仿此断，则心易无不验矣。”

','{"sourceId":"user-meihua","startChar":18034,"endChar":18923,"startLine":577,"endLine":582}','historical-reference-not-proven-outcome');
占官讼，以体为主，用为对辞之人与官讼之应。体卦宜旺，用卦宜衰。体宜用生，不宜生用。宜生体，不宜克体。是故体克用者，已胜人；用克体者，人胜己。体生用，非为失理，或因官有所丧；用生体，不止得理，或因讼有所得。体用比和，官讼最吉。非但扶持之力，必有主和之义。

','{"sourceId":"user-meihua","startChar":18923,"endChar":19060,"startLine":583,"endLine":585}','historical-reference-not-proven-outcome');
占坟墓以体为主，用为坟墓。体克用，葬之吉；用克体，葬之凶。体生用，葬之主运退；用生体，葬之主兴隆，有荫益后嗣。体用比和，乃为吉地。大宜葬，葬之吉昌。
上为用体之诀，始发十八章占例，以示后学之法则。然庶务之多，岂止十八占而已乎！然此十八占，乃大事之切要者，占者以类而推之可也。


','{"sourceId":"user-meihua","startChar":19060,"endChar":19209,"startLine":586,"endLine":590}','historical-reference-not-proven-outcome');
CREATE VIEW moving_line_details AS SELECT l.*,d.changed_hexagram_id,h.name AS changed_hexagram_name,d.structure_json,d.editorial_notes_json FROM lines l JOIN line_details d USING(hexagram_id,position) JOIN hexagrams h ON h.id=d.changed_hexagram_id;
COMMIT;
